      d.groups.filter((gr) => gr.stage === st.id).forEach((gr) => { const m = eqs.filter((e) => gr.members.includes(e.id)); if (!m.length) return; html += n('group:' + gr.id, 'eq', gr.name); m.forEach((e) => { grouped.add(e.id); html += n('eq:' + e.id, 'eq', '   ' + e.name); }); });
