    const crumb = sub.kind === 'eq' ? `${esc(d.plant.name)} › ${esc(stage(e.stage).name)}${e.group ? ' › ' + esc(group(e.group).name) : ''}` : sub.kind === 'group' ? `${esc(d.plant.name)} › ${esc(stage(group(sub.id).stage).name)}` : sub.kind === 'stage' ? esc(d.plant.name) : '';
